'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import StatCard from '@/components/dashboard/stat-card';
import RecentActivity from '@/components/dashboard/recent-activity';

// Types
interface DashboardSummary {
  total_products: number;
  total_branches: number;
  total_sales_today: number;
  total_revenue_today: number;
  low_stock_count: number;
  out_of_stock_count: number;
  pending_transfers: number;
}

// Mock data for development
const mockSummary: DashboardSummary = {
  total_products: 1247,
  total_branches: 5,
  total_sales_today: 234,
  total_revenue_today: 12450.50,
  low_stock_count: 23,
  out_of_stock_count: 8,
  pending_transfers: 12,
};

const mockActivities = [
  {
    id: '1',
    type: 'sale' as const,
    description: 'New sale completed - Receipt #12345',
    user: 'John Doe',
    timestamp: new Date(Date.now() - 1000 * 60 * 30).toISOString(),
    branch: 'Main Branch',
  },
  {
    id: '2',
    type: 'transfer' as const,
    description: 'Stock transfer dispatched from Branch A to Branch B',
    user: 'Jane Smith',
    timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(),
    branch: 'Branch A',
  },
  {
    id: '3',
    type: 'stock_adjustment' as const,
    description: 'Stock adjustment: Product XYZ increased by 50 units',
    user: 'Mike Johnson',
    timestamp: new Date(Date.now() - 1000 * 60 * 60 * 4).toISOString(),
    branch: 'Main Branch',
  },
  {
    id: '4',
    type: 'new_product' as const,
    description: 'New product added: Wireless Mouse Pro',
    user: 'Sarah Wilson',
    timestamp: new Date(Date.now() - 1000 * 60 * 60 * 6).toISOString(),
    branch: 'Main Branch',
  },
];

export default function DashboardPage() {
  const [summary, setSummary] = useState<DashboardSummary>(mockSummary);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        // In a real app, you would fetch from the API
        // const response = await apiClient.get('/dashboard/summary');
        // setSummary(response.data);
        
        // For now, use mock data
        setTimeout(() => {
          setSummary(mockSummary);
          setLoading(false);
        }, 1000);
      } catch {
        setError('Failed to load dashboard data');
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  if (loading) {
    return (
      <Layout>
        <div className="animate-pulse">
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="bg-gray-200 rounded-lg h-32"></div>
            ))}
          </div>
        </div>
      </Layout>
    );
  }

  if (error) {
    return (
      <Layout>
        <div className="bg-red-50 border border-red-200 rounded-md p-4">
          <div className="text-red-800">{error}</div>
        </div>
      </Layout>
    );
  }

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
        {/* Page Header */}
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
          <p className="mt-1 text-sm text-gray-600">
            Welcome to your POS Stock Management Dashboard
          </p>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
          <StatCard
            title="Total Products"
            value={summary.total_products}
            change={12}
            changeType="increase"
            icon="products"
          />
          <StatCard
            title="Total Branches"
            value={summary.total_branches}
            change={0}
            changeType="increase"
            icon="branches"
          />
          <StatCard
            title="Today's Revenue"
            value={summary.total_revenue_today}
            change={8}
            changeType="increase"
            icon="revenue"
          />
          <StatCard
            title="Low Stock Alerts"
            value={summary.low_stock_count + summary.out_of_stock_count}
            change={-5}
            changeType="decrease"
            icon="alerts"
          />
        </div>

        {/* Additional Stats */}
        <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
          <div className="card p-6">
            <h3 className="text-lg font-medium text-primary mb-4">Today&apos;s Sales</h3>
            <div className="text-3xl font-bold text-primary">{summary.total_sales_today}</div>
            <p className="text-sm text-text-secondary mt-1">Transactions completed</p>
          </div>
          
          <div className="card p-6">
            <h3 className="text-lg font-medium text-primary mb-4">Pending Transfers</h3>
            <div className="text-3xl font-bold text-primary">{summary.pending_transfers}</div>
            <p className="text-sm text-text-secondary mt-1">Awaiting processing</p>
          </div>
          
          <div className="card p-6">
            <h3 className="text-lg font-medium text-primary mb-4">Out of Stock</h3>
            <div className="text-3xl font-bold text-error">{summary.out_of_stock_count}</div>
            <p className="text-sm text-text-secondary mt-1">Items need restocking</p>
          </div>
        </div>

        {/* Recent Activity */}
        <div className="lg:grid lg:grid-cols-2 lg:gap-6">
          <RecentActivity activities={mockActivities} />
          
          {/* Quick Actions */}
          <div className="card">
            <div className="px-6 py-5">
              <h3 className="text-lg font-medium text-primary mb-4">
                Quick Actions
              </h3>
              <div className="grid grid-cols-2 gap-4">
                <button className="p-4 text-center bg-primary/10 rounded-lg hover:bg-primary/20 transition-colors">
                  <div className="text-2xl mb-2">📦</div>
                  <div className="text-sm font-medium text-primary">New Product</div>
                </button>
                <button className="p-4 text-center bg-success/10 rounded-lg hover:bg-success/20 transition-colors">
                  <div className="text-2xl mb-2">💰</div>
                  <div className="text-sm font-medium text-primary">New Sale</div>
                </button>
                <button className="p-4 text-center bg-info/10 rounded-lg hover:bg-info/20 transition-colors">
                  <div className="text-2xl mb-2">🔄</div>
                  <div className="text-sm font-medium text-primary">Transfer Stock</div>
                </button>
                <button className="p-4 text-center bg-warning/10 rounded-lg hover:bg-warning/20 transition-colors">
                  <div className="text-2xl mb-2">📊</div>
                  <div className="text-sm font-medium text-primary">View Reports</div>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
    </AuthGuard>
  );
}
